from lib import R
F = "35-mains-bakes-skillet-legumes.txt"
def M(t, cu, prep, cook, serv, ings, steps, meals="Dinner, Main dish"):
    R(F, t, "Main", cu, prep, cook, serv, meals, ings, steps)

# ---------------- casseroles and bakes ----------------
M("Chicken and Broccoli Rice Casserole", "American", 15, 45, 6, "250 g|rice; 600 ml|chicken stock; 500 g|chicken breast, diced; 300 g|broccoli, in small florets; 1|onion, chopped; 200 ml|milk; 150 g|cheddar, grated; 1 tsp|garlic powder; |salt; |black pepper",
  "Heat the oven to 190°C (375°F) and grease a 23 x 33 cm baking dish / Stir the rice, stock, milk, onion, garlic powder, 1 tsp salt and pepper together in the dish, then scatter over the chicken / Cover tightly with foil and bake 35 minutes / Stir in the broccoli and half the cheese, top with the rest and bake uncovered 10 to 15 minutes until the rice is tender and the top is golden")
M("Beef Enchilada Casserole", "Tex-Mex", 15, 30, 6, "500 g|ground beef; 1|onion, chopped; 1 can|black beans, drained; 2 tbsp|taco seasoning; 400 ml|enchilada sauce; 8|corn tortillas, torn; 200 g|cheddar, grated; 4 tbsp|sour cream",
  "Heat the oven to 190°C (375°F) / Brown the beef and onion, then stir in the beans, taco seasoning and half the enchilada sauce / Layer a third of the tortillas in a baking dish, then half the beef and a third of the cheese. Repeat, finish with tortillas, the remaining sauce and cheese / Bake 25 to 30 minutes until bubbling. Serve with sour cream")
M("Tater Tot Casserole", "American", 15, 40, 6, "500 g|ground beef; 1|onion, chopped; 300 g|green beans, chopped; 1 can|cream of mushroom soup; 120 ml|milk; 150 g|cheddar, grated; 600 g|tater tots; |salt; |black pepper",
  "Heat the oven to 200°C (400°F) / Brown the beef with the onion, season, and spread in a baking dish / Mix the soup and milk and pour over, then scatter over the green beans and cheese / Cover with the tater tots in a neat layer and bake 35 to 40 minutes until the tots are crisp")
M("Baked Penne with Sausage and Peppers", "Italian-American", 15, 30, 6, "400 g|penne; 4|italian sausages, sliced; 2|bell peppers, sliced; 1|onion, sliced; 700 ml|marinara sauce; 200 g|mozzarella, grated; 40 g|parmesan, grated",
  "Heat the oven to 200°C (400°F). Cook the penne 3 minutes less than the packet says and drain / Brown the sausage, then soften the peppers and onion in the same pan / Mix everything with the marinara and half the mozzarella in a baking dish / Top with the remaining mozzarella and parmesan and bake 20 minutes until bubbling")
M("Chicken Parmesan Pasta Bake", "Italian-American", 15, 30, 6, "400 g|rigatoni; 500 g|cooked chicken, chopped; 700 ml|marinara sauce; 200 g|mozzarella, grated; 50 g|parmesan, grated; 40 g|panko; 1 tbsp|olive oil; 1 tsp|italian seasoning",
  "Heat the oven to 200°C (400°F). Cook the rigatoni until just short of tender and drain / Mix the pasta, chicken, marinara and half the mozzarella in a baking dish / Top with the rest of the mozzarella. Mix the panko, parmesan, oil and seasoning and scatter over / Bake 20 to 25 minutes until golden and crisp")
M("Turkey and Sweet Potato Cottage Pie", "British", 20, 35, 6, "800 g|sweet potatoes, peeled and cubed; 500 g|ground turkey; 1|onion, chopped; 2|carrots, diced; 150 g|peas; 2 tbsp|tomato paste; 300 ml|chicken stock; 1 tbsp|worcestershire sauce; 2 tbsp|butter; |salt; |black pepper",
  "Boil the sweet potatoes for 12 minutes until soft, drain and mash with the butter and salt / Brown the turkey with the onion and carrots, then stir in the tomato paste, stock and Worcestershire sauce and simmer 10 minutes. Stir in the peas / Spoon into a baking dish, top with the mash and rough up the surface / Bake at 200°C (400°F) for 20 to 25 minutes until bubbling at the edges")
M("Spinach and Mushroom Lasagne", "Italian", 30, 45, 8, "12|lasagna noodles; 500 g|mushrooms, sliced; 300 g|spinach; 500 g|ricotta; 1|egg; 700 ml|marinara sauce; 250 g|mozzarella, grated; 50 g|parmesan, grated; 2 cloves|garlic, chopped; 1 tbsp|olive oil",
  "Heat the oven to 190°C (375°F). Fry the mushrooms in the oil until browned, add the garlic and spinach and cook until wilted, then squeeze out excess liquid / Mix the ricotta with the egg, half the parmesan and salt / Layer sauce, noodles, ricotta, vegetables and mozzarella in a baking dish three times, finishing with sauce, mozzarella and parmesan / Cover with foil and bake 30 minutes, uncover and bake 15 minutes more. Rest 15 minutes before slicing")
M("Tuna Noodle Casserole", "American", 10, 30, 6, "300 g|egg noodles; 2 can|tuna, drained; 1 can|cream of mushroom soup; 200 ml|milk; 150 g|peas; 120 g|cheddar, grated; 40 g|breadcrumbs; 1 tbsp|butter, melted",
  "Heat the oven to 190°C (375°F) and cook the noodles until just tender / Mix the soup and milk, then fold in the noodles, tuna, peas and most of the cheese / Spread in a baking dish, top with the remaining cheese and the breadcrumbs mixed with butter / Bake 20 to 25 minutes until golden")
M("Mexican Rice and Bean Bake", "Tex-Mex", 10, 45, 6, "250 g|rice; 1 can|black beans, drained; 1 can|kidney beans, drained; 150 g|sweetcorn; 400 g|salsa; 500 ml|vegetable stock; 2 tsp|cumin; 150 g|cheddar, grated; 1 handful|cilantro",
  "Heat the oven to 190°C (375°F) / Stir the rice, beans, corn, salsa, stock and cumin together in a baking dish / Cover tightly with foil and bake 40 minutes until the rice is tender / Scatter over the cheese and bake uncovered 5 minutes more. Finish with cilantro")
M("Cheesy Potato and Ham Bake", "American", 15, 55, 6, "1 kg|potatoes, thinly sliced; 250 g|ham, diced; 1|onion, thinly sliced; 300 ml|heavy cream; 200 ml|milk; 2 cloves|garlic, crushed; 150 g|cheddar, grated; |salt; |black pepper",
  "Heat the oven to 180°C (350°F) and butter a baking dish / Warm the cream, milk and garlic with 1 tsp salt and pepper / Layer the potatoes, ham, onion and cheese, finishing with potatoes and cheese, then pour over the cream / Cover with foil and bake 40 minutes, uncover and bake 15 minutes more until tender and golden")

# ---------------- skillet proteins ----------------
M("Pan-Seared Cod with Lemon Caper Butter", "French", 5, 10, 2, "2|cod fillets; 1 tbsp|flour; 1 tbsp|olive oil; 3 tbsp|butter; 1 tbsp|capers; 1|lemon; 1 tbsp|parsley, chopped; |salt",
  "Pat the fish dry, season and dust with flour / Sear in the oil 3 to 4 minutes a side until golden and just flaking / Remove the fish, add the butter and capers and cook until the butter is nutty brown / Add the lemon juice and parsley and spoon over the fish")
M("Chicken Thighs in Creamy Mustard Sauce", "French", 5, 25, 4, "8|chicken thighs, boneless; 1 tbsp|olive oil; 2|shallots, chopped; 150 ml|white wine; 150 ml|heavy cream; 3 tbsp|dijon mustard (or half whole grain); 1 tbsp|tarragon, chopped; |salt; |black pepper",
  "Season the chicken and brown well in the oil, 5 minutes a side; remove / Soften the shallots in the pan, add the wine and boil until reduced by half / Stir in the cream and mustard and return the chicken. Simmer 8 to 10 minutes until cooked through / Finish with tarragon")
M("Honey Garlic Pork Chops", "American", 5, 15, 4, "4|pork chops; 1 tbsp|vegetable oil; 4 cloves|garlic, minced; 4 tbsp|honey; 2 tbsp|soy sauce; 1 tbsp|apple cider vinegar; 1 tbsp|butter; |salt; |black pepper",
  "Season the chops and sear in the oil 4 to 5 minutes a side until browned and cooked to 63°C (145°F); rest on a plate / Lower the heat, add the butter and garlic for 30 seconds / Add the honey, soy sauce and vinegar and bubble 2 minutes until syrupy / Return the chops and turn them in the glaze")
M("Sesame-Crusted Tuna Steaks", "Japanese", 5, 4, 2, "2|tuna steaks; 3 tbsp|sesame seeds; 1 tbsp|vegetable oil; 2 tbsp|soy sauce; 1 tsp|rice vinegar; 1 tsp|ginger, grated; 1|green onion, sliced",
  "Season the tuna lightly and press the sesame seeds onto both sides / Sear in a very hot pan with the oil for 1 to 2 minutes a side, leaving the middle pink / Mix the soy sauce, vinegar and ginger / Slice the tuna and serve with the dipping sauce and green onion, with rice or salad")
M("Turkey Cutlets with Sage Butter", "Italian", 5, 10, 4, "600 g|turkey breast, cut into 4 thin cutlets; 30 g|flour; 1 tbsp|olive oil; 3 tbsp|butter; 10|sage leaves; 1|lemon; |salt; |black pepper",
  "Season the cutlets and dust with flour / Fry in the oil 2 to 3 minutes a side until golden and cooked through; keep warm / Add the butter and sage to the pan and cook until the sage is crisp and the butter is golden / Squeeze in a little lemon and pour over the turkey")
M("Steak with Peppercorn Sauce", "French", 5, 15, 2, "2|ribeye steaks; 1 tbsp|black peppercorns, crushed; 1 tbsp|vegetable oil; 1 tbsp|butter; 1|shallot, chopped; 2 tbsp|brandy; 150 ml|beef stock; 100 ml|heavy cream; |salt",
  "Season the steaks with salt and press the crushed peppercorns into one side / Sear in the hot oil 3 to 4 minutes a side for medium-rare, then rest / Soften the shallot in the butter, add the brandy and let it bubble away / Add the stock and boil 2 minutes, then the cream, and simmer until it coats a spoon. Serve over the steaks")
M("Creamy Sun-Dried Tomato Chicken", "Italian", 5, 20, 4, "4|chicken breasts; 1 tbsp|olive oil; 3 cloves|garlic, minced; 80 g|sun-dried tomatoes, chopped; 200 ml|heavy cream; 100 ml|chicken stock; 40 g|parmesan, grated; 1 tsp|italian seasoning; 1 handful|spinach; |salt",
  "Season the chicken and sear in the oil 5 to 6 minutes a side until cooked through; remove / Fry the garlic and sun-dried tomatoes for 1 minute / Add the cream, stock, seasoning and parmesan and simmer 3 minutes / Stir in the spinach, return the chicken and spoon the sauce over")
M("Cajun Blackened White Fish", "Cajun", 5, 8, 4, "4|white fish fillets; 1 tbsp|cajun seasoning; 1 tsp|smoked paprika; 1 tsp|dried thyme; 2 tbsp|butter, melted; 1 tbsp|vegetable oil; 1|lemon",
  "Mix the Cajun seasoning, paprika and thyme / Brush the fish with the melted butter and coat in the spices / Cook in a very hot cast-iron pan with the oil 3 to 4 minutes a side until blackened and flaky (open a window) / Serve with lemon wedges")
M("Pan-Fried Salmon with Dill Yogurt", "Scandinavian", 5, 10, 2, "2|salmon fillets; 1 tbsp|olive oil; 150 g|greek yogurt; 1 tbsp|dill, chopped; 1|lemon; 1 clove|garlic, grated; |salt; |black pepper",
  "Mix the yogurt, dill, garlic, a squeeze of lemon and salt / Season the salmon and cook skin side down in the oil for 5 minutes until crisp, then turn for 2 to 3 minutes / Serve with the dill yogurt and lemon wedges")
M("Pork Medallions with Cider Sauce", "British", 10, 15, 4, "600 g|pork tenderloin, sliced into medallions; 1 tbsp|vegetable oil; 1 tbsp|butter; 1|apple, sliced; 1|shallot, chopped; 200 ml|apple juice, or dry cider; 2 tbsp|heavy cream; 1 tsp|dijon mustard; |salt; |black pepper",
  "Season the pork and sear in the oil 2 to 3 minutes a side; remove / Fry the apple and shallot in the butter for 3 minutes / Add the apple juice and boil until reduced by half, then stir in the cream and mustard / Return the pork for 2 minutes to finish cooking")
M("Chicken Milanese with Arugula", "Italian", 15, 10, 4, "2|chicken breasts, halved and pounded thin; 40 g|flour; 2|eggs; 100 g|breadcrumbs; 30 g|parmesan, grated; 4 tbsp|vegetable oil; 100 g|arugula; 150 g|cherry tomatoes, halved; 1|lemon",
  "Coat the chicken in flour, then egg, then breadcrumbs mixed with parmesan / Shallow-fry in the oil 3 minutes a side until golden and cooked; drain / Toss the arugula and tomatoes with lemon juice, olive oil and salt / Serve the chicken topped with the salad and lemon wedges")
M("Trout Amandine", "French", 5, 10, 2, "2|trout fillets; 1 tbsp|flour; 3 tbsp|butter; 40 g|almonds, sliced; 1|lemon; 1 tbsp|parsley, chopped; |salt",
  "Season the trout and dust with flour / Fry in 1 tbsp butter 2 to 3 minutes a side; plate / Add the rest of the butter and the almonds and cook until golden / Add lemon juice and parsley and spoon over the fish")
M("Greek Shrimp Saganaki", "Greek", 10, 15, 4, "500 g|shrimp, peeled; 2 tbsp|olive oil; 1|onion, chopped; 2 cloves|garlic; 1 can|canned tomatoes; 1 tsp|dried oregano; 0.5 tsp|chili flakes; 100 g|feta, crumbled; 1 handful|parsley",
  "Soften the onion and garlic in the oil for 5 minutes / Add the tomatoes, oregano and chili and simmer 8 minutes / Nestle in the shrimp, scatter over the feta and cook covered 4 minutes until the shrimp are pink / Finish with parsley and serve with bread")
M("Tofu Steaks with Ginger Glaze", "Asian", 10, 12, 2, "400 g|firm tofu, cut into 4 slabs and pressed; 1 tbsp|cornstarch; 1 tbsp|vegetable oil; 2 tbsp|tamari; 1 tbsp|maple syrup; 1 tbsp|ginger, grated; 1 tsp|rice vinegar; 1|green onion, sliced",
  "Pat the tofu dry and dust with cornstarch / Fry in the oil 4 to 5 minutes a side until crisp / Mix the tamari, maple syrup, ginger and vinegar, pour into the pan and let it bubble and coat the tofu / Scatter with green onion and serve with rice and greens")
M("Chicken Paprikash", "Hungarian", 10, 35, 4, "8|chicken thighs, boneless; 2 tbsp|vegetable oil; 2|onions, chopped; 2 tbsp|sweet paprika; 1|red bell pepper, diced; 1 tbsp|tomato paste; 300 ml|chicken stock; 150 g|sour cream; 1 tbsp|flour; 300 g|egg noodles",
  "Brown the chicken in the oil and remove / Cook the onions and pepper gently for 8 minutes, then stir in the paprika and tomato paste off the heat / Add the stock and chicken, cover and simmer 20 minutes / Mix the sour cream with the flour, stir in and heat gently without boiling. Serve over egg noodles")
M("Bratwurst with Sauerkraut and Potatoes", "German", 10, 30, 4, "8|bratwurst; 700 g|potatoes, in chunks; 400 g|sauerkraut, drained; 1|onion, sliced; 1|apple, grated; 1 tsp|caraway seeds; 1 tbsp|vegetable oil; 2 tbsp|whole grain mustard",
  "Boil the potatoes until tender, about 15 minutes / Brown the bratwurst in the oil for 10 minutes, turning / In the same pan soften the onion, then add the sauerkraut, apple, caraway and a splash of water and heat through for 5 minutes / Serve the sausages on the sauerkraut with the potatoes and mustard")
M("Duck Breast with Cherry Sauce", "French", 10, 20, 2, "2|duck breasts; 150 g|cherries, pitted; 100 ml|red wine; 1 tbsp|honey; 1 tsp|balsamic vinegar; 1 sprig|thyme; |salt; |black pepper",
  "Score the duck skin and season / Put skin side down in a cold pan, then cook over medium heat 8 to 10 minutes until the fat renders and the skin is crisp. Turn and cook 3 to 4 minutes for pink, then rest / Pour off most of the fat, add the cherries, wine, honey, vinegar and thyme and simmer until syrupy / Slice the duck and spoon over the sauce")

# ---------------- burgers ----------------
BG = [
 ("Lamb and Feta Burgers", "Greek", "500 g|ground lamb; 80 g|feta, crumbled; 1 tsp|dried oregano; 1 clove|garlic, grated", "Mix the lamb, feta, oregano, garlic and pepper and shape into 4 patties", 4, "4 tbsp|tzatziki; 1|red onion, sliced; 1 handful|lettuce"),
 ("Salmon Burgers with Lemon Mayo", "American", "500 g|salmon fillet, skinned and finely chopped; 40 g|panko; 1|egg; 2|green onions, sliced; 1|lemon, zested", "Mix the salmon, panko, egg, green onions, lemon zest and salt and shape into 4 patties. Chill 15 minutes", 3, "4 tbsp|mayonnaise; 1 handful|lettuce; 1|tomato, sliced"),
 ("Smoky Chickpea Burgers", "International", "2 can|chickpeas, drained; 50 g|breadcrumbs; 1|egg; 1 tsp|smoked paprika; 1 tsp|cumin; 1|carrot, grated", "Mash the chickpeas roughly, mix in the breadcrumbs, egg, paprika, cumin, carrot and salt, and shape into 4 patties", 4, "4 tbsp|mayonnaise; 1 handful|lettuce; 1|tomato, sliced"),
 ("Mushroom Swiss Burgers", "American", "600 g|ground beef; 250 g|mushrooms, sliced; 1 tbsp|butter; 4 slices|swiss cheese", "Shape the beef into 4 patties slightly wider than the buns and season well. Fry the mushrooms in the butter until golden and set aside", 4, "2 tbsp|dijon mustard; 1 handful|lettuce"),
 ("Chicken Burgers with Pesto Mayo", "Italian", "500 g|ground chicken; 30 g|parmesan, grated; 30 g|breadcrumbs; 1 clove|garlic, grated", "Mix the chicken, parmesan, breadcrumbs, garlic and salt and shape into 4 patties with wet hands", 5, "2 tbsp|pesto; 3 tbsp|mayonnaise; 1 handful|arugula; 1|tomato, sliced"),
 ("Halloumi Burgers with Roasted Peppers", "Mediterranean", "250 g|halloumi, cut into 4 thick slices; 1 jar|roasted red peppers; 1 tsp|dried oregano", "Pat the halloumi dry and sprinkle with oregano", 2, "4 tbsp|hummus; 1 handful|arugula"),
 ("Teriyaki Pineapple Turkey Burgers", "Hawaiian", "500 g|ground turkey; 3 tbsp|teriyaki sauce; 2|green onions, sliced; 4 rings|pineapple", "Mix the turkey with 1 tbsp teriyaki sauce, the green onions and pepper and shape into 4 patties", 5, "1 handful|lettuce; 2 tbsp|mayonnaise"),
 ("Smash Burgers", "American", "500 g|ground beef, 20% fat; 4 slices|american cheese; 1|onion, very thinly sliced", "Divide the beef into 8 loose balls", 1, "4 tbsp|ketchup; 8 slices|pickles"),
]
for t, cu, pat, prep_s, mins, tops in BG:
    if "Smash" in t:
        cook = ["Heat a heavy pan or griddle until very hot", "Put in 2 balls at a time, cover with onion slices and smash flat with a sturdy spatula. Season and cook 2 minutes until deeply browned, then flip", "Add cheese, stack two patties per burger and cook 1 minute more"]
    elif "Halloumi" in t:
        cook = ["Fry the halloumi in a dry pan " + str(mins) + " minutes a side until golden"]
    else:
        cook = ["Cook in a lightly oiled pan or on the grill " + str(mins) + " to " + str(mins + 1) + " minutes a side until cooked through" + (" (71°C/160°F for beef, 74°C/165°F for poultry)" if "beef" in pat or "chicken" in pat or "turkey" in pat else "")]
        if "Mushroom Swiss" in t: cook.append("Top with the mushrooms and cheese, cover for 1 minute to melt")
        if "Pineapple" in t: cook.append("Brush with the rest of the teriyaki sauce and grill the pineapple rings 2 minutes a side")
        if "Pesto" in t: cook.append("Mix the pesto with the mayonnaise")
        if "Salmon" in t: cook.append("Mix the mayonnaise with a squeeze of the zested lemon")
    st = [prep_s] + cook + ["Toast the buns and build the burgers with the toppings"]
    M(t, cu, 15, 10 if "Smash" not in t else 8, 4, pat + "; 4|burger buns; 1 tbsp|vegetable oil; |salt; |black pepper; " + tops, st, "Lunch, Dinner, Main dish")

# ---------------- risotto ----------------
RS = [
 ("Lemon Asparagus Risotto", "250 g|asparagus, in short lengths; 1|lemon, zest and juice", "Add the asparagus for the last 5 minutes", "the lemon zest and juice", "vegetable stock"),
 ("Tomato and Mozzarella Risotto", "200 g|cherry tomatoes, halved; 2 tbsp|tomato paste; 125 g|mozzarella, diced; 1 handful|basil", "Stir the tomato paste in with the rice and add the cherry tomatoes halfway", "the mozzarella and torn basil", "vegetable stock"),
 ("Shrimp and Lemon Risotto", "300 g|shrimp, peeled; 1|lemon, zest and juice; 1 tbsp|parsley, chopped", "Add the shrimp for the last 4 minutes", "the lemon and parsley", "chicken stock"),
 ("Spinach and Blue Cheese Risotto", "150 g|spinach; 80 g|blue cheese, crumbled; 30 g|walnuts, toasted", "Stir in the spinach for the last 2 minutes", "the blue cheese, with walnuts on top", "vegetable stock"),
 ("Beet Risotto with Goat Cheese", "2|beets, cooked and grated; 100 g|goat cheese; 1 tbsp|dill, chopped", "Stir in the beets halfway through", "half the goat cheese, crumbling the rest on top with the dill", "vegetable stock"),
 ("Chicken and Leek Risotto", "300 g|chicken breast, diced; 2|leeks, sliced; 1 tsp|dried thyme", "Brown the chicken first and set aside; soften the leeks with the onion and return the chicken halfway", "the thyme", "chicken stock"),
 ("Saffron Risotto", "1 pinch|saffron", "Soak the saffron in a ladle of hot stock and add it with the first stock", "a little extra parmesan", "chicken stock"),
]
for t, extra, mid, fin, stock in RS:
    M(t, "Italian", 10, 30, 4, "300 g|arborio rice; 1.2 l|" + stock + "; 1|onion, finely chopped; 2 tbsp|olive oil; 1 tbsp|butter; 100 ml|white wine; 40 g|parmesan, grated; |salt; |black pepper; " + extra,
      ["Keep the stock hot in a pan. Soften the onion in the oil for 5 minutes", "Add the rice and stir 1 minute until glossy, then add the wine and let it bubble away",
       "Add the stock a ladle at a time, stirring often and waiting until each is absorbed, for 18 to 20 minutes until the rice is creamy but still has a little bite. " + mid,
       "Off the heat, beat in the butter, parmesan and " + fin + ". Season, cover for 2 minutes and serve"])

# ---------------- dals and legumes ----------------
M("Moong Dal with Spinach", "Indian", 10, 30, 4, "200 g|moong dal, rinsed; 1 l|water; 0.5 tsp|turmeric; 150 g|spinach; 2 tbsp|ghee; 1 tsp|cumin seeds; 2 cloves|garlic, sliced; 1|green chili, slit; 1|tomato, chopped; |salt",
  "Simmer the dal with the water, turmeric and salt for 25 minutes until soft / Stir in the spinach until wilted / Heat the ghee, fry the cumin seeds, garlic and chili until fragrant, add the tomato for 2 minutes and pour over the dal / Serve with rice or flatbread")
M("Sambar-Style Lentils with Vegetables", "South Indian", 15, 35, 4, "200 g|toor dal; 1.2 l|water; 0.5 tsp|turmeric; 2|carrots, in chunks; 1|eggplant, in chunks; 1|onion, chopped; 2 tbsp|sambar powder; 1 tbsp|tamarind paste; 1 tsp|mustard seeds; 10|curry leaves; 2 tbsp|vegetable oil; |salt",
  "Simmer the dal with the water and turmeric for 25 minutes until soft, then mash / Add the vegetables, onion, sambar powder, tamarind and salt and simmer 10 to 12 minutes until tender / Heat the oil, fry the mustard seeds until they pop, add the curry leaves and pour over / Serve with rice")
M("Rajma (Kidney Bean Curry)", "Indian", 10, 30, 4, "2 can|kidney beans, drained; 2 tbsp|vegetable oil; 1 tsp|cumin seeds; 1|onion, finely chopped; 3 cloves|garlic; 1 tbsp|ginger, grated; 1 can|canned tomatoes; 1 tsp|garam masala; 1 tsp|ground coriander; 0.5 tsp|chili powder; 300 g|rice; |salt",
  "Fry the cumin seeds in the oil, then the onion for 8 minutes until golden / Add the garlic, ginger and spices for 1 minute, then the tomatoes and cook 8 minutes until thick / Add the beans and 300 ml water, mash a few beans to thicken and simmer 15 minutes / Serve with rice")
M("West African Black-Eyed Pea Stew", "West African", 10, 30, 4, "2 can|black-eyed peas, drained; 2 tbsp|vegetable oil; 1|onion, chopped; 1|red bell pepper, chopped; 1|scotch bonnet, minced; 1 can|canned tomatoes; 2 tbsp|tomato paste; 1 tsp|smoked paprika; 400 ml|vegetable stock; 1|sweet potato, diced; |salt",
  "Soften the onion and pepper in the oil for 6 minutes with the scotch bonnet / Add the tomato paste and paprika for 1 minute, then the tomatoes, stock and sweet potato / Simmer 15 minutes, then add the peas and cook 8 minutes more until thick / Serve with rice or fried plantains")
M("Ful Medames", "Egyptian", 5, 15, 4, "2 can|fava beans, with liquid; 3 cloves|garlic, crushed; 1 tsp|cumin; 1|lemon; 3 tbsp|olive oil; 1|tomato, diced; 1 handful|parsley, chopped; 4|pita; |salt",
  "Warm the beans with their liquid for 10 minutes and mash about half / Stir in the garlic, cumin, lemon juice and salt / Spoon into bowls, pour over the olive oil and top with tomato and parsley / Serve with warm pita", "Breakfast, Lunch, Dinner, Main dish")
M("Cuban-Style Black Beans and Rice", "Cuban", 10, 25, 4, "2 can|black beans, with liquid; 2 tbsp|olive oil; 1|onion, chopped; 1|green bell pepper, chopped; 4 cloves|garlic; 1 tsp|cumin; 1 tsp|dried oregano; 1|bay leaf; 1 tbsp|red wine vinegar; 300 g|rice; |salt",
  "Cook the rice / Make a sofrito: soften the onion, pepper and garlic in the oil for 8 minutes / Add the beans with their liquid, cumin, oregano and bay leaf and simmer 15 minutes, mashing some beans to thicken / Stir in the vinegar, season and serve over the rice")
M("Feijoada-Style Black Bean Stew", "Brazilian", 15, 45, 6, "3 can|black beans, drained; 300 g|smoked sausage, sliced; 4 slices|bacon, chopped; 300 g|pork shoulder, cubed; 1|onion, chopped; 4 cloves|garlic; 2|bay leaves; 600 ml|chicken stock; 1|orange; 300 g|rice",
  "Fry the bacon until crisp, then brown the pork and sausage in the fat / Add the onion and garlic for 5 minutes / Add the beans, stock and bay leaves and simmer gently for 40 minutes until the pork is tender and the stew thick / Serve with rice and orange slices")
M("Tuscan White Beans with Kale", "Italian", 5, 20, 4, "2 can|cannellini beans, drained; 3 tbsp|olive oil; 4 cloves|garlic, sliced; 0.5 tsp|chili flakes; 1 sprig|rosemary; 200 g|kale, shredded; 1 can|canned tomatoes; 30 g|parmesan, grated | opt; 4 slices|bread, crusty",
  "Warm the garlic, chili and rosemary in the oil until fragrant / Add the tomatoes and simmer 5 minutes, then the beans and kale with a splash of water / Cover and cook 10 minutes until the kale is tender / Serve with parmesan and toasted bread", "Lunch, Dinner, Main dish")
M("Ethiopian-Style Red Lentil Stew", "Ethiopian", 10, 30, 4, "250 g|red lentils, rinsed; 3 tbsp|vegetable oil; 2|onions, finely chopped; 3 cloves|garlic; 1 tbsp|ginger, grated; 2 tbsp|berbere; 2 tbsp|tomato paste; 900 ml|water; |salt",
  "Cook the onions slowly in the oil for 10 minutes until soft and golden / Add the garlic, ginger, berbere and tomato paste and cook 2 minutes / Add the lentils and water and simmer 20 minutes, stirring, until thick and soft / Season and serve with flatbread or rice")
M("Dal Makhani-Style Black Lentils", "Indian", 10, 60, 6, "250 g|urad dal, soaked overnight; 1 can|kidney beans, drained; 3 tbsp|butter; 1|onion, finely chopped; 1 tbsp|ginger garlic paste; 1 can|canned tomatoes; 1 tsp|garam masala; 1 tsp|chili powder; 100 ml|heavy cream; |salt",
  "Simmer the soaked lentils in plenty of water for 45 minutes until very soft; drain, keeping some liquid / Cook the onion in the butter for 8 minutes, add the ginger garlic paste and spices, then the tomatoes for 8 minutes / Add the lentils, beans and 400 ml of their liquid and simmer 15 minutes, stirring and mashing a little / Stir in the cream and serve with rice or naan")
